namespace {
using namespace biglybtc::core;
std::size_t cases=0,assertions=0;
void check(bool value,const char* message){++assertions;if(!value){throw std::runtime_error(message);}}
PassiveSpeedObservation input(std::int64_t time,std::int64_t up=25600,std::int64_t down=51200,std::int64_t rtt=10,bool rebase=false){return {time,up,down,rtt,rebase};}
void append(PassiveSpeedMapper& mapper,PassiveSpeedObservation value){check(bool(mapper.observe(value)),"qualified literal observation rejected");}
PassiveSpeedSnapshot take(const PassiveSpeedMapper& mapper){auto result=mapper.snapshot();check(bool(result),"bounded snapshot failed");return std::move(*result);}
template<std::size_t N>void trace(PassiveSpeedMapper& mapper,const std::array<source_literals::Point,N>& points){std::int64_t now=1;for(const auto& point:points){append(mapper,input(now++,point.up,point.down,point.rtt));const auto snapshot=take(mapper);check(snapshot.history.back().uploadBin==point.x&&snapshot.history.back().downloadBin==point.y&&snapshot.history.back().metric==point.metric,"source trace point mismatch");}}
std::string bs(const std::string& value){return std::to_string(value.size())+":"+value;}
std::string bi(std::int64_t value){return "i"+std::to_string(value)+"e";}
std::string record(std::int64_t speed,const std::string& type="0",std::int64_t when=0,const std::string& metric="-1",std::int64_t hits=1){return "d1:s"+bi(speed)+"1:h"+bi(hits)+"1:w"+bi(when)+"1:m"+bs(metric)+(type.empty()?"":"1:t"+bs(type))+"e";}
template<std::size_t N>std::string badList(const std::array<std::int64_t,N>& values){std::string result="l";for(auto speed:values){result+=record(speed);}return result+"e";}
std::string seeded(const std::string& up,const std::string& down="",const std::string& badUp="",const std::string& badDown="",const std::string& goodUp="",const std::string& goodDown=""){
  std::string result="d";for(const auto& [key,value]:std::array<std::pair<std::string,std::string>,6>{{{"upcap",up},{"downcap",down},{"lbus",badUp},{"lbds",badDown},{"bgu",goodUp},{"bgd",goodDown}}}){if(!value.empty()){result+=bs(key)+value;}}return result+"e";
}
void seed(PassiveSpeedMapper& mapper,const std::string& value){check(bool(mapper.restoreSaved(value)),"valid source-format saved seed rejected");}
void speed(PassiveSpeedMapper& mapper,std::int64_t time,std::int64_t up=25600,std::int64_t down=51200){check(bool(mapper.observeSpeed({time,up,down})),"qualified rate-only source tick rejected");}

}
