 run("source-rate-division-and-adjacent-averaging-precede-expansion",[]{PassiveSpeedMapper mapper;append(mapper,input(1,511,1023,0));append(mapper,input(2,513,1025,0));const auto value=take(mapper);check(value.history[0].uploadBin==0&&value.history[0].downloadBin==1&&value.history[1].uploadBin==1&&value.history[1].downloadBin==3,"rate division/average order changed");check(value.history[0].normalizedRttMillis==1&&value.history[1].normalizedRttMillis==1,"source zero RTT normalization changed");});
 run("actual-zero-inputs-keep-observed-zero-and-source-sub5k-floor",[]{PassiveSpeedMapper mapper;append(mapper,input(1,0,0,0));append(mapper,input(2,0,0,0));const auto value=take(mapper);check(value.history[0].input.uploadBytesPerSecond==0&&value.history[1].input.downloadBytesPerSecond==0,"known actual0 became missing");check(value.upload&&value.download&&value.upload->bytesPerSecond==1&&value.download->bytesPerSecond==1,"source single-bin/null-selection floor lost");check(value.upload->segments.empty()&&value.upload->hits==0&&value.upload->metricRating==1,"source singleton segment policy changed");});
