 run("literal-three-sample-variance-does-not-divide-deviation-squares",[]{PassiveSpeedMapper mapper;for(unsigned i=0;i<3;++i){append(mapper,input(i+1,25600,51200,10*(i+1)));const auto value=take(mapper);check(value.history.back().metric==source_literals::VarianceMetrics[i],"source variance metric mismatch");}const auto value=take(mapper);check(value.zones.size()==2&&value.zones[0].metric==3&&value.zones[1].metric==10,"region metric integer midpoint mismatch");});
 run("literal-new-bad-region-resets-prior-bin-credit",[]{PassiveSpeedMapper mapper;trace(mapper,source_literals::Choke);const auto value=take(mapper);check(value.currentMetricRating==-1&&value.upload&&value.download,"source choke did not produce current estimates");check(value.upload->bytesPerSecond==25600&&value.download->bytesPerSecond==51200&&value.upload->metricRating==-1&&value.upload->hits==1,"smallest-bad/reset source policy mismatch");check(value.upload->segments.size()==2&&value.upload->segments[1].start==25600&&value.upload->segments[1].end==38400&&value.upload->segments[1].averageMetric==150,"source bad span mismatch");});
 run("source-final-singleton-segment-is-not-silently-repaired",[]{PassiveSpeedMapper mapper;for(std::int64_t i=1;i<=4;++i){append(mapper,input(i,25600,51200,425));}const auto value=take(mapper);check(value.currentMetricRating==0&&value.upload&&value.upload->bytesPerSecond==1&&value.upload->hits==0,"omitted-tail/no-candidate source outcome changed");check(value.upload->metricRating==1&&value.upload->segments.size()==1&&value.upload->segments[0].start==0&&value.upload->segments[0].end==25344,"source final singleton was invented");});
